-- Editable templates in all seven languages. Transport and approval are separate.
WITH locales(language,prefix,suffix,bodies) AS (VALUES
('en',E'Booking: {{booking_code}}\nService: {{service}}\nOrigin: {{origin}}\nDestination: {{destination}}\n\n',E'\n\nOpen your customer portal: {{portal_url}}','{"auth_otp":"Your one-time code is {{otp}}. It expires in 10 minutes and can be used once. Do not share this code. If you did not request it, ignore this email.","booking_submitted":"Thank you. UKR will review your booking and confirm the next steps.\n\nMark {{booking_code}} on every box. Send the packing list, HS codes, your contact number and a clear description of the goods. Warehouse receiving address: {{warehouse_address}}.","booking_accepted":"UKR has accepted your booking. Follow the receiving instructions below.\n\nMark {{booking_code}} on every box. Send the packing list, HS codes, your contact number and a clear description of the goods. Warehouse receiving address: {{warehouse_address}}.","goods_received":"Details: {{message}}.\n\nWe received {{pieces}} pieces. Photos and details: {{document_url}}. Missing packing lists or required information may delay shipment. The customer is responsible for ensuring the goods are lawful and permitted for shipment; counterfeit or restricted goods are not accepted.","in_transit":"Details: {{message}}.\nStatus: {{status}}\nETA: {{eta}}","on_hold":"Reason: {{reason}}. Required action: {{action}}.","arrival_notice":"Your shipment has arrived. Please review the next steps and any payment requirements in your portal.","invoice_issued":"Invoice {{invoice_code}}: {{amount}} {{currency}}. Due: {{due_date}}. Document: {{document_url}}.","payment_confirmed":"Your payment of {{amount}} {{currency}} has been confirmed. Receipt: {{document_url}}.","ready_for_delivery":"Your cargo has been released for delivery planning. UKR will confirm the delivery arrangements.","delivered":"Delivered to {{recipient_name}}. Delivery evidence: {{document_url}}.","feedback_request":"Please rate your shipping experience and share your comments: {{feedback_url}}.","fcl_so_released":"Details: {{message}}.","fcl_bl_approval":"Please review the draft bill of lading in your portal and approve it or request corrections: {{document_url}}.","currency_rate_reminder":"Please update {{pair}} ({{rate_type}}) for {{rate_date}}. The daily deadline is {{due_time}}; the grace cut-off is {{cutoff_time}} {{timezone}}.","staff_invitation":"You have been invited to UKR. Open your private activation link and choose a password: {{activation_url}}. This link expires in 48 hours."}'::jsonb),
('ar',E'الحجز: {{booking_code}}\nالخدمة: {{service}}\nالمنشأ: {{origin}}\nالوجهة: {{destination}}\n\n',E'\n\nافتح بوابة العملاء: {{portal_url}}','{"auth_otp":"رمزك لمرة واحدة هو {{otp}}. تنتهي صلاحيته بعد 10 دقائق ويُستخدم مرة واحدة. لا تشاركه مع أحد. تجاهل الرسالة إن لم تطلب الرمز.","booking_submitted":"شكراً لك. ستراجع UKR الحجز وتؤكد الخطوات التالية.\n\nاكتب {{booking_code}} على كل صندوق. أرسل قائمة التعبئة ورموز HS ورقم التواصل ووصفاً واضحاً للبضائع. عنوان استلام المستودع: {{warehouse_address}}.","booking_accepted":"قبلت UKR حجزك. اتبع تعليمات الاستلام أدناه.\n\nاكتب {{booking_code}} على كل صندوق. أرسل قائمة التعبئة ورموز HS ورقم التواصل ووصفاً واضحاً للبضائع. عنوان استلام المستودع: {{warehouse_address}}.","goods_received":"التفاصيل: {{message}}.\n\nاستلمنا {{pieces}} قطعة. الصور والتفاصيل: {{document_url}}. قد يؤدي غياب قائمة التعبئة أو المعلومات المطلوبة إلى تأخير الشحنة. العميل مسؤول عن قانونية البضائع والسماح بشحنها؛ لا تُقبل البضائع المقلدة أو المقيدة.","in_transit":"التفاصيل: {{message}}.\nالحالة: {{status}}\nالوصول المتوقع: {{eta}}","on_hold":"السبب: {{reason}}. الإجراء المطلوب: {{action}}.","arrival_notice":"وصلت شحنتك. راجع الخطوات التالية ومتطلبات الدفع في بوابتك.","invoice_issued":"الفاتورة {{invoice_code}}: {{amount}} {{currency}}. الاستحقاق: {{due_date}}. المستند: {{document_url}}.","payment_confirmed":"تم تأكيد دفع {{amount}} {{currency}}. الإيصال: {{document_url}}.","ready_for_delivery":"تم الإفراج عن بضائعك لتخطيط التسليم. ستؤكد UKR ترتيبات التسليم.","delivered":"تم التسليم إلى {{recipient_name}}. إثبات التسليم: {{document_url}}.","feedback_request":"قيّم تجربة الشحن وشارك ملاحظاتك: {{feedback_url}}.","fcl_so_released":"التفاصيل: {{message}}.","fcl_bl_approval":"راجع مسودة بوليصة الشحن في بوابتك واعتمدها أو اطلب تصحيحها: {{document_url}}.","currency_rate_reminder":"يرجى تحديث {{pair}} ({{rate_type}}) ليوم {{rate_date}}. الموعد اليومي {{due_time}} ونهاية المهلة {{cutoff_time}} بتوقيت {{timezone}}.","staff_invitation":"دُعيت إلى UKR. افتح رابط التفعيل الخاص واختر كلمة مرور: {{activation_url}}. تنتهي صلاحيته خلال 48 ساعة."}'),
('ru',E'Бронирование: {{booking_code}}\nУслуга: {{service}}\nОтправление: {{origin}}\nНазначение: {{destination}}\n\n',E'\n\nОткрыть кабинет клиента: {{portal_url}}','{"auth_otp":"Ваш одноразовый код: {{otp}}. Он действует 10 минут и используется один раз. Никому не сообщайте код. Если вы его не запрашивали, проигнорируйте письмо.","booking_submitted":"Спасибо. UKR рассмотрит заявку и подтвердит дальнейшие действия.\n\nУкажите {{booking_code}} на каждой коробке. Отправьте упаковочный лист, коды ТН ВЭД, контактный номер и точное описание груза. Адрес склада: {{warehouse_address}}.","booking_accepted":"UKR приняла бронирование. Следуйте инструкциям приёмки ниже.\n\nУкажите {{booking_code}} на каждой коробке. Отправьте упаковочный лист, коды ТН ВЭД, контактный номер и точное описание груза. Адрес склада: {{warehouse_address}}.","goods_received":"Сведения: {{message}}.\n\nПолучено мест: {{pieces}}. Фотографии и сведения: {{document_url}}. Отсутствие упаковочного листа или обязательных данных может задержать отправку. Клиент отвечает за законность и допустимость груза; контрафактные или ограниченные к перевозке товары не принимаются.","in_transit":"Сведения: {{message}}.\nСтатус: {{status}}\nРасчётное прибытие: {{eta}}","on_hold":"Причина: {{reason}}. Необходимое действие: {{action}}.","arrival_notice":"Ваш груз прибыл. Проверьте дальнейшие действия и требования к оплате в кабинете.","invoice_issued":"Счёт {{invoice_code}}: {{amount}} {{currency}}. Срок оплаты: {{due_date}}. Документ: {{document_url}}.","payment_confirmed":"Оплата {{amount}} {{currency}} подтверждена. Квитанция: {{document_url}}.","ready_for_delivery":"Груз разрешён к планированию доставки. UKR подтвердит условия доставки.","delivered":"Доставлено получателю {{recipient_name}}. Подтверждение: {{document_url}}.","feedback_request":"Оцените перевозку и оставьте комментарий: {{feedback_url}}.","fcl_so_released":"Сведения: {{message}}.","fcl_bl_approval":"Проверьте проект коносамента в кабинете и подтвердите его либо запросите исправления: {{document_url}}.","currency_rate_reminder":"Обновите {{pair}} ({{rate_type}}) на {{rate_date}}. Ежедневный срок: {{due_time}}, окончание льготного периода: {{cutoff_time}} {{timezone}}.","staff_invitation":"Вы приглашены в UKR. Откройте личную ссылку и задайте пароль: {{activation_url}}. Ссылка действует 48 часов."}'),
('fr',E'Réservation: {{booking_code}}\nService: {{service}}\nOrigine: {{origin}}\nDestination: {{destination}}\n\n',E'\n\nOuvrir votre espace client: {{portal_url}}','{"auth_otp":"Votre code à usage unique est {{otp}}. Il expire dans 10 minutes. Ne le communiquez à personne. Ignorez ce message si vous n’avez pas demandé ce code.","booking_submitted":"Merci. UKR examinera votre demande et confirmera les prochaines étapes.\n\nInscrivez {{booking_code}} sur chaque colis. Envoyez la liste de colisage, les codes SH, votre numéro de téléphone et une description précise des marchandises. Adresse de réception : {{warehouse_address}}.","booking_accepted":"UKR a accepté votre réservation. Suivez les instructions de réception ci-dessous.\n\nInscrivez {{booking_code}} sur chaque colis. Envoyez la liste de colisage, les codes SH, votre numéro de téléphone et une description précise des marchandises. Adresse de réception : {{warehouse_address}}.","goods_received":"Détails : {{message}}.\n\nNous avons reçu {{pieces}} colis. Photos et détails : {{document_url}}. L’absence de liste de colisage ou d’informations obligatoires peut retarder l’envoi. Le client doit s’assurer que les marchandises sont légales et autorisées à l’expédition ; les produits contrefaits ou soumis à restriction ne sont pas acceptés.","in_transit":"Détails : {{message}}.\nStatut: {{status}}\nArrivée estimée: {{eta}}","on_hold":"Motif : {{reason}}. Action requise : {{action}}.","arrival_notice":"Votre expédition est arrivée. Consultez les prochaines étapes et les paiements requis dans votre espace client.","invoice_issued":"Facture {{invoice_code}} : {{amount}} {{currency}}. Échéance : {{due_date}}. Document : {{document_url}}.","payment_confirmed":"Votre paiement de {{amount}} {{currency}} a été confirmé. Reçu : {{document_url}}.","ready_for_delivery":"Votre marchandise est libérée pour la planification de la livraison. UKR confirmera les modalités.","delivered":"Livré à {{recipient_name}}. Justificatif de livraison : {{document_url}}.","feedback_request":"Évaluez votre expérience et partagez vos commentaires : {{feedback_url}}.","fcl_so_released":"Détails : {{message}}.","fcl_bl_approval":"Vérifiez le projet de connaissement dans votre espace client et approuvez-le ou demandez des corrections : {{document_url}}.","currency_rate_reminder":"Mettez à jour {{pair}} ({{rate_type}}) pour le {{rate_date}}. Échéance quotidienne : {{due_time}} ; fin du délai de grâce : {{cutoff_time}} {{timezone}}.","staff_invitation":"Vous êtes invité à UKR. Ouvrez votre lien privé et choisissez un mot de passe : {{activation_url}}. Le lien expire dans 48 heures."}'),
('ur',E'بکنگ: {{booking_code}}\nسروس: {{service}}\nروانگی: {{origin}}\nمنزل: {{destination}}\n\n',E'\n\nکسٹمر پورٹل کھولیں: {{portal_url}}','{"auth_otp":"آپ کا ایک بار استعمال ہونے والا کوڈ {{otp}} ہے۔ یہ 10 منٹ بعد ختم ہو جائے گا۔ کوڈ کسی کو نہ بتائیں۔ اگر آپ نے درخواست نہیں کی تو اس ای میل کو نظر انداز کریں۔","booking_submitted":"شکریہ۔ UKR آپ کی بکنگ کا جائزہ لے کر اگلے مراحل کی تصدیق کرے گا۔\n\nہر ڈبے پر {{booking_code}} لکھیں۔ پیکنگ لسٹ، HS کوڈ، رابطہ نمبر اور سامان کی واضح تفصیل بھیجیں۔ گودام کا وصولی پتہ: {{warehouse_address}}۔","booking_accepted":"UKR نے آپ کی بکنگ قبول کر لی ہے۔ نیچے دی گئی وصولی ہدایات پر عمل کریں۔\n\nہر ڈبے پر {{booking_code}} لکھیں۔ پیکنگ لسٹ، HS کوڈ، رابطہ نمبر اور سامان کی واضح تفصیل بھیجیں۔ گودام کا وصولی پتہ: {{warehouse_address}}۔","goods_received":"تفصیل: {{message}}۔\n\nہم نے {{pieces}} پیکج وصول کیے ہیں۔ تصاویر اور تفصیل: {{document_url}}۔ پیکنگ لسٹ یا ضروری معلومات نہ ہونے سے شپمنٹ میں تاخیر ہو سکتی ہے۔ قانونی اور اجازت یافتہ سامان بھیجنا کسٹمر کی ذمہ داری ہے؛ نقلی یا پابندی والا سامان قبول نہیں کیا جاتا۔","in_transit":"تفصیل: {{message}}۔\nحالت: {{status}}\nمتوقع آمد: {{eta}}","on_hold":"وجہ: {{reason}}۔ مطلوبہ کارروائی: {{action}}۔","arrival_notice":"آپ کی شپمنٹ پہنچ گئی ہے۔ پورٹل میں اگلے مراحل اور ادائیگی کی ضروریات دیکھیں۔","invoice_issued":"انوائس {{invoice_code}}: {{amount}} {{currency}}۔ آخری تاریخ: {{due_date}}۔ دستاویز: {{document_url}}۔","payment_confirmed":"آپ کی {{amount}} {{currency}} ادائیگی کی تصدیق ہو گئی ہے۔ رسید: {{document_url}}۔","ready_for_delivery":"آپ کا سامان ڈیلیوری کی منصوبہ بندی کے لیے ریلیز کر دیا گیا ہے۔ UKR انتظامات کی تصدیق کرے گا۔","delivered":"{{recipient_name}} کو پہنچا دیا گیا۔ ڈیلیوری کا ثبوت: {{document_url}}۔","feedback_request":"شپنگ کے تجربے کی درجہ بندی کریں اور رائے دیں: {{feedback_url}}۔","fcl_so_released":"تفصیل: {{message}}۔","fcl_bl_approval":"پورٹل میں بل آف لیڈنگ کا مسودہ دیکھ کر منظوری دیں یا درستگی مانگیں: {{document_url}}۔","currency_rate_reminder":"{{rate_date}} کے لیے {{pair}} ({{rate_type}}) اپ ڈیٹ کریں۔ روزانہ آخری وقت {{due_time}} اور رعایتی حد {{cutoff_time}} {{timezone}} ہے۔","staff_invitation":"آپ کو UKR میں مدعو کیا گیا ہے۔ نجی ایکٹیویشن لنک کھول کر پاس ورڈ منتخب کریں: {{activation_url}}۔ لنک 48 گھنٹے میں ختم ہو گا۔"}'),
('hi',E'बुकिंग: {{booking_code}}\nसेवा: {{service}}\nमूल स्थान: {{origin}}\nगंतव्य: {{destination}}\n\n',E'\n\nग्राहक पोर्टल खोलें: {{portal_url}}','{"auth_otp":"आपका एक बार इस्तेमाल होने वाला कोड {{otp}} है। यह 10 मिनट में समाप्त होगा। इसे किसी से साझा न करें। आपने कोड नहीं माँगा तो यह ईमेल अनदेखा करें।","booking_submitted":"धन्यवाद। UKR आपकी बुकिंग की समीक्षा करके अगले कदम की पुष्टि करेगा।\n\nहर बॉक्स पर {{booking_code}} लिखें। पैकिंग सूची, HS कोड, संपर्क नंबर और माल का स्पष्ट विवरण भेजें। गोदाम का प्राप्ति पता: {{warehouse_address}}।","booking_accepted":"UKR ने आपकी बुकिंग स्वीकार कर ली है। नीचे दिए प्राप्ति निर्देशों का पालन करें।\n\nहर बॉक्स पर {{booking_code}} लिखें। पैकिंग सूची, HS कोड, संपर्क नंबर और माल का स्पष्ट विवरण भेजें। गोदाम का प्राप्ति पता: {{warehouse_address}}।","goods_received":"विवरण: {{message}}।\n\nहमें {{pieces}} पैकेज प्राप्त हुए। तस्वीरें और विवरण: {{document_url}}। पैकिंग सूची या आवश्यक जानकारी न मिलने पर शिपमेंट में देरी हो सकती है। माल कानूनी और शिपिंग के लिए अनुमत होना ग्राहक की ज़िम्मेदारी है; नकली या प्रतिबंधित माल स्वीकार नहीं किया जाता।","in_transit":"विवरण: {{message}}।\nस्थिति: {{status}}\nअनुमानित आगमन: {{eta}}","on_hold":"कारण: {{reason}}। आवश्यक कार्रवाई: {{action}}।","arrival_notice":"आपकी शिपमेंट आ गई है। पोर्टल में अगले कदम और आवश्यक भुगतान देखें।","invoice_issued":"चालान {{invoice_code}}: {{amount}} {{currency}}। देय तिथि: {{due_date}}। दस्तावेज़: {{document_url}}।","payment_confirmed":"आपके {{amount}} {{currency}} भुगतान की पुष्टि हो गई है। रसीद: {{document_url}}।","ready_for_delivery":"आपका माल डिलीवरी की योजना के लिए जारी कर दिया गया है। UKR डिलीवरी व्यवस्था की पुष्टि करेगा।","delivered":"{{recipient_name}} को पहुँचाया गया। डिलीवरी प्रमाण: {{document_url}}।","feedback_request":"अपने शिपिंग अनुभव को रेट करें और राय दें: {{feedback_url}}।","fcl_so_released":"विवरण: {{message}}।","fcl_bl_approval":"पोर्टल में बिल ऑफ लीडिंग का मसौदा देखकर मंज़ूरी दें या सुधार माँगें: {{document_url}}।","currency_rate_reminder":"{{rate_date}} के लिए {{pair}} ({{rate_type}}) अपडेट करें। दैनिक समय {{due_time}} और अतिरिक्त समय की सीमा {{cutoff_time}} {{timezone}} है।","staff_invitation":"आपको UKR में आमंत्रित किया गया है। निजी सक्रियण लिंक खोलकर पासवर्ड चुनें: {{activation_url}}। लिंक 48 घंटे में समाप्त होगा।"}'),
('zh',E'预订: {{booking_code}}\n服务: {{service}}\n始发地: {{origin}}\n目的地: {{destination}}\n\n',E'\n\n打开客户门户: {{portal_url}}','{"auth_otp":"您的一次性验证码为 {{otp}}，10 分钟内有效，仅可使用一次。请勿向任何人透露。如果您未申请验证码，请忽略本邮件。","booking_submitted":"感谢您。UKR 将审核预订并确认后续步骤。\n\n请在每个箱子上标注 {{booking_code}}，并提供装箱单、HS 编码、联系电话和清晰的货物说明。仓库收货地址：{{warehouse_address}}。","booking_accepted":"UKR 已接受您的预订。请遵循以下收货说明。\n\n请在每个箱子上标注 {{booking_code}}，并提供装箱单、HS 编码、联系电话和清晰的货物说明。仓库收货地址：{{warehouse_address}}。","goods_received":"详情：{{message}}。\n\n已收到 {{pieces}} 件。照片及详情：{{document_url}}。缺少装箱单或必要资料可能导致延误。客户须确保货物合法且允许运输；不接受假冒或受限制货物。","in_transit":"详情：{{message}}。\n状态: {{status}}\n预计到达: {{eta}}","on_hold":"原因：{{reason}}。需要采取的措施：{{action}}。","arrival_notice":"您的货物已抵达。请在客户门户查看后续步骤及付款要求。","invoice_issued":"账单 {{invoice_code}}：{{amount}} {{currency}}。到期日：{{due_date}}。文件：{{document_url}}。","payment_confirmed":"已确认您的付款 {{amount}} {{currency}}。收据：{{document_url}}。","ready_for_delivery":"您的货物已放行，可安排派送。UKR 将确认配送安排。","delivered":"已交付给 {{recipient_name}}。签收凭证：{{document_url}}。","feedback_request":"请评价运输体验并留下意见：{{feedback_url}}。","fcl_so_released":"详情：{{message}}。","fcl_bl_approval":"请在门户审核提单草稿，批准或申请更正：{{document_url}}。","currency_rate_reminder":"请更新 {{rate_date}} 的 {{pair}}（{{rate_type}}）。每日更新时间为 {{due_time}}，宽限截止时间为 {{cutoff_time}} {{timezone}}。","staff_invitation":"您已受邀加入 UKR。请打开专属激活链接并设置密码：{{activation_url}}。链接将在 48 小时后失效。"}')),
templates(code,body_key,standalone,subjects) AS (VALUES
('auth_otp','auth_otp',true,'{"en":"Your UKR sign-in code","ar":"رمز الدخول إلى UKR","ru":"Код входа UKR","fr":"Votre code de connexion UKR","ur":"آپ کا UKR لاگ ان کوڈ","hi":"आपका UKR साइन-इन कोड","zh":"您的 UKR 登录验证码"}'::jsonb),
('booking_submitted','booking_submitted',false,'{"en":"Booking submitted","ar":"تم تقديم الحجز","ru":"Заявка подана","fr":"Demande de réservation reçue","ur":"بکنگ جمع ہو گئی","hi":"बुकिंग जमा हो गई","zh":"预订已提交"}'),
