('staff_invitation','staff_invitation',true,'{"en":"Your UKR staff invitation","ar":"دعوتك إلى فريق UKR","ru":"Приглашение в команду UKR","fr":"Votre invitation au personnel UKR","ur":"UKR عملے کی دعوت","hi":"UKR स्टाफ आमंत्रण","zh":"UKR 员工邀请"}')),
rendered AS (SELECT t.code,l.language,t.subjects->>l.language AS subject,CASE WHEN t.standalone THEN l.bodies->>t.body_key ELSE l.prefix||(l.bodies->>t.body_key)||l.suffix END AS body FROM templates t CROSS JOIN locales l)
INSERT INTO email_templates(code,language,subject,body,variables,approved)
SELECT r.code,r.language,r.subject,r.body,COALESCE((SELECT jsonb_agg(v ORDER BY v) FROM (SELECT DISTINCT (m)[1] AS v FROM regexp_matches(r.subject||r.body,'\{\{([a-z_]+)\}\}','g') m) variable_names),'[]'::jsonb),false FROM rendered r;
